def fixture_window_bug(start, stop, position):
    """Stop is exclusive."""
    return start <= position <= stop

def fixture_window_correct(start, stop, position):
    """Stop is exclusive."""
    return start <= position < stop

def fixture_tags_bug(tag, tags=set()):
    """Each omitted tags argument gets a fresh set."""
    tags.add(tag)
    return sorted(tags)

def fixture_tags_correct(tag, tags=None):
    """Each omitted tags argument gets a fresh set."""
    tags = {tag} if tags is None else tags | {tag}
    return sorted(tags)
